import{_ as e,o as t,c as o,a3 as n}from"./chunks/framework.DeRSg1wr.js";const l=JSON.parse('{"title":"Javaagent 接入已移除","description":"TLog 2.0 已移除 tlog-agent，旧链接保留并提供迁移入口。","frontmatter":{"title":"Javaagent 接入已移除","date":"2022-09-12T13:35:36.000Z","permalink":"/pages/4b07c7/","description":"TLog 2.0 已移除 tlog-agent，旧链接保留并提供迁移入口。"},"headers":[],"relativePath":"pages/4b07c7/index.md","filePath":"10.文档/050.Javaagent方式/010.Javaagent接入方式.md"}'),r={name:"pages/4b07c7/index.md"};function g(c,a,d,_,i,s){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="javaagent-接入已移除" tabindex="-1">Javaagent 接入已移除 <a class="header-anchor" href="#javaagent-接入已移除" aria-label="Permalink to &quot;Javaagent 接入已移除&quot;">​</a></h1><p>TLog 2.0 不再提供 <code>tlog-agent</code> 模块或 javaagent 接入。旧版 agent 不应与 2.0 依赖混用。</p><p>迁移时加入应用所需的 TLog starter，删除 JVM 中指向 <code>tlog-agent.jar</code> 的 <code>-javaagent</code> 参数，再配置日志输出。logback 应用可以使用普通 encoder 和 <code>%X{tl}</code>；详细步骤见<a href="/guide/quick-start/">快速开始</a>和<a href="/guide/upgrade/">升级指南</a>。</p><p>原接入依赖对日志类的字节码修改，受类加载时机、Spring Boot fat jar 和现代 JDK 强封装影响。2.0 使用日志框架扩展点，不再要求通过 JVM 开放参数维持旧增强逻辑。</p>',4)])])}const v=e(r,[["render",g]]);export{l as __pageData,v as default};
